/**
 * The review ask's one rule (v2.6007, punch list #185), shared by every door that mints a {rate} link: the reply box
 * (`ratingLinkIo.ts`, v2.5877), a press on Today's sends (`offers/offersIo.ts`'s `withRatingLink`) and the morning run
 * (`supabase/functions/_shared/ratingMint.ts`, through the kernel copy). The blank, the link it becomes, which texts
 * carry the ask, and the decision `mint_customer_rating` makes: a job whose rating was answered is never asked again;
 * a fresh unanswered ask to the same person about the same job is reused, so a re-send never forks the asked count;
 * otherwise a new ask is minted. Pure, with no imports, so the edge takes it as it stands.
 */

/** The blank a quick reply or the Review asked step's line carries until the link is minted. */
export const RATE_BLANK = '{rate}'

/** The rating page's path with its token, as `ratingUrl` writes it and `carriesRatingAsk` reads it. */
export const RATE_PATH = '/rate?t='

/** How long an unanswered ask stays fresh enough to reuse, as the RPC counts it. */
export const REUSE_DAYS = 30

/** The rating page for a token: `https://clicktooling.com/rate?t=…`. */
export const ratingUrl = (token: string, origin: string): string => `${origin.replace(/\/$/, '')}${RATE_PATH}${encodeURIComponent(token)}`

/** Whether a line still waits on the rating's link. */
export const needsRatingLink = (body: string): boolean => body.includes(RATE_BLANK)

/**
 * Whether a text carries the review ask: the link the blank became, or the blank itself. The flow's `review_asked` fact
 * reads this off an out text, so the app's own line counts as the ask, whatever its words.
 */
export const carriesRatingAsk = (body: string): boolean => body.includes(RATE_PATH) || body.includes(RATE_BLANK)

/** The least of a `customer_ratings` row the answered rule reads. */
export interface RatingAnswer {
  job_id: string | null
  answered_at: string | null
}

/** A `customer_ratings` row as the mint's decision reads it. */
export interface RatingAskRow extends RatingAnswer {
  contact_id: string
  asked_at: string
  public_token: string
}

/** Whether this job's rating was answered already, by anyone asked on it. A job-less ask answers for no job. */
export function answeredAlready(rows: readonly RatingAnswer[], jobId: string | null): boolean {
  return jobId !== null && rows.some((r) => r.job_id === jobId && r.answered_at !== null)
}

/** The jobs among these asks whose rating was answered, so a window can hold each one's offer. */
export function answeredJobs(rows: readonly RatingAnswer[]): Set<string> {
  const out = new Set<string>()
  for (const r of rows) if (r.answered_at !== null && r.job_id !== null) out.add(r.job_id)
  return out
}

export type RatingAskDecision = { refused: 'answered' } | { reuse: string } | { mint: true }

/**
 * What a mint for this person about this job does, from the job's asks: refused once the job was answered; the newest
 * fresh unanswered ask to the same person about the same job reused, by its token; else a new ask.
 */
export function decideRatingAsk(rows: readonly RatingAskRow[], input: { contactId: string; jobId: string | null; now: Date }): RatingAskDecision {
  if (answeredAlready(rows, input.jobId)) return { refused: 'answered' }
  const since = new Date(input.now.getTime() - REUSE_DAYS * 24 * 3600 * 1000).toISOString()
  const fresh = rows
    .filter((r) => r.contact_id === input.contactId && r.job_id === input.jobId && r.answered_at === null && r.asked_at > since)
    .sort((a, b) => b.asked_at.localeCompare(a.asked_at))[0]
  return fresh ? { reuse: fresh.public_token } : { mint: true }
}
